@startuml

class Customer {
  + Name : string
  + Surname : string
  + Email : string
  + Telephone : string
  + HomeAddress : string
}

class Order {
  + TotalCost : double
  + EstimatedDeliveryTime : time
  + Status : string
}

class Dish {
  + Name : string
  + PreparationTime : int
}

class Payment {
  + CreditCardDetails : string
  + IsSuccessful : boolean
}

Customer "1" -- "*" Order
Order "1" -- "1..*" Dish
Order "1" -- "0..1" Payment

@enduml

